from decimal import Decimal, InvalidOperation
from typing import Any


_ZERO = Decimal("0")
_EIGHTY_PERCENT = Decimal("0.8")


def _decimal(value: Any) -> Decimal:
    """Convert legacy numeric values, treating empty or missing values as zero."""
    if value is None or value == "":
        return _ZERO
    try:
        return Decimal(str(value).strip() or "0")
    except (InvalidOperation, ValueError):
        return _ZERO


def _account_key(value: Any) -> tuple[int, Any]:
    """Provide deterministic primary-key ordering for numeric or textual account IDs."""
    try:
        return (0, Decimal(str(value)))
    except (InvalidOperation, ValueError):
        return (1, str(value))


def _id_key(value: Any) -> tuple[str, Any]:
    """Normalize numeric-looking IDs so numeric strings and numbers match."""
    try:
        return ("numeric", Decimal(str(value)))
    except (InvalidOperation, ValueError):
        return ("text", str(value))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    exposures: dict[tuple[str, Any], Decimal] = {}

    for order in orders:
        if order.get("DEL_FLG") != "Y" and order.get("STAT_CD") == "I":
            key = _id_key(order.get("ACCT_ID"))
            exposures[key] = exposures.get(key, _ZERO) + _decimal(order.get("TOT_AMT"))

    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]

    for index in sorted(
        eligible_indexes,
        key=lambda item: _account_key(accounts[item].get("ACCT_ID")),
    ):
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")
        exposure = exposures.get(_id_key(acct_id), _ZERO)
        credit_limit = _decimal(account.get("CRED_LIMIT"))
        credit_hold = account.get("CRED_HOLD", "")

        if exposure > credit_limit and credit_hold != "Y":
            credit_hold = "Y"
            account["CRED_HOLD"] = credit_hold
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * _EIGHTY_PERCENT and credit_hold == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
